// Данные лент времени (история Казахстана, всемирная история, история России).
// Строка: год|категория|название en|ru|kk|почему важно en|ru|kk[|подпись даты en|ru|kk].
// Год до н. э. - отрицательный, «~» перед годом - дата примерная («около»).
// Категории: s - государства и правители, w - войны и восстания, c - культура и наука, e - экономика и общество.

import { L } from '../pools/gen.js';

function parse(src) {
  return src
    .trim()
    .split('\n')
    .map((line) => {
      const f = line.split('|').map((x) => x.trim());
      const c = f[0].startsWith('~');
      return {
        y: Number(c ? f[0].slice(1) : f[0]),
        c,
        k: f[1],
        t: L(f[2], f[3], f[4]),
        d: L(f[5], f[6], f[7]),
        s: f[8] ? L(f[8], f[9], f[10]) : null,
      };
    })
    .sort((a, b) => a.y - b.y);
}

